                (d.note ? '<div class="col-span-2"><span class="font-semibold text-gray-500">Note / Contratto:</span><p class="text-gray-600 text-xs">' + escapeHtml(d.note) + '</p></div>' : '') +
                '</div>';
            const dIdx = allDDTs.indexOf(d);
